  "scanDatabaseForPii": {"operationId":"scanDatabaseForPii","method":"POST","path":"/v1/projects/{project_id}/databases/{database_id}/scan-pii","summary":"Scan a database for likely-PII columns","description":"Connects to the upstream database read-only, inspects information_schema and samples column values against PII heuristics, and returns ranked masking suggestions. Suggestions are advisory — the operator reviews them and applies the ones they want into a policy profile's masking rules. Nothing is auto-applied.","parameters":[{"name":"project_id","in":"path","required":true,"type":"string","description":"Unique project identifier (prefixed, e.g. prj_xxx)."},{"name":"database_id","in":"path","required":true,"type":"string","description":"Unique database identifier (prefixed, e.g. db_xxx)."}],"requestBodyType":"","requestBodyRequired":false,"responseType":"{ error?: string; scanned_columns: number; scanned_tables: number; suggestions: ({ column: string; confidence: number; data_type: string; mask_kind: \"redact\" | \"null\" | \"hash\"; pii_type: \"email\" | \"phone\" | \"ssn\" | \"credit_card\" | \"ip_address\" | \"full_name\" | \"street_address\" | \"date_of_birth\" | \"national_id\" | \"passport\" | \"bank_account\" | \"api_secret\" | \"other\"; reasons: string[]; sample_match_count?: number; sample_size?: number; schema: string; table: string })[]; truncated?: boolean }","responseStatus":"200"},
  "getSchemaCatalog": {"operationId":"getSchemaCatalog","method":"GET","path":"/v1/projects/{project_id}/databases/{database_id}/schema-catalog","summary":"Read a database's schema catalog","description":"Connects to the upstream database read-only and returns its user relations (tables and views) and columns. Powers table/column autocomplete and view-aware warnings in the policy editor — relation kind distinguishes a view (whose masking/row-filters apply to the view itself, not its base tables) from a base table, and a per-column is_binary flag flags columns that mask to NULL. System schemas are excluded; nothing is persisted.","parameters":[{"name":"project_id","in":"path","required":true,"type":"string","description":"Unique project identifier (prefixed, e.g. prj_xxx)."},{"name":"database_id","in":"path","required":true,"type":"string","description":"Unique database identifier (prefixed, e.g. db_xxx)."}],"requestBodyType":"","requestBodyRequired":false,"responseType":"{ error?: string; relations: ({ columns: ({ data_type: string; is_binary: boolean; name: string })[]; kind: \"table\" | \"view\" | \"materialized_view\" | \"other\"; name: string; schema: string })[]; scanned_columns: number; scanned_relations: number; truncated?: boolean }","responseStatus":"200"},
